using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.Serialization;using V15Voice;
[DataContract]public sealed class VanFixtures {[DataMember]public List<VanCase> cases;}
[DataContract]public sealed class VanCase {[DataMember]public string name;[DataMember]public string sha256;[DataMember]public List<VanStage> stages;[DataMember]public List<int> old_wav_changed_ids;}
[DataContract]public sealed class VanStage {[DataMember]public int number;[DataMember]public List<int> ids;[DataMember]public double probe_natural;[DataMember]public double final_natural;[DataMember]public double final_speed;[DataMember]public List<VanAttempt> attempts;}
[DataContract]public sealed class VanAttempt {[DataMember]public List<AiCueText> cues;[DataMember]public bool accepted;}
public static class VanRegressionTests {
 static int count;static void Check(bool v,string label){if(!v)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static Wave Tone(double sec){return new Wave{Rate=24000,Samples=Enumerable.Range(0,(int)Math.Round(sec*24000)).Select(i=>(short)(5000*Math.Cos(i*.055))).ToArray()};}
 sealed class ReplayEngine:KokoroEngine {public Dictionary<string,double> Durations;public int Calls;public override void CheckFiles(){}public override Wave Generate(string text,double speed,string file){Calls++;return Tone(Durations[text]/speed);}}
 public static int Main(){try{
  string fixtures=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"source/fixtures/van215");var data=LocalAi.Parse<VanFixtures>(File.ReadAllText(Path.Combine(fixtures,"audit.json")));string folder=Path.Combine(Path.GetTempPath(),"V15 VAN synthetic "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);Directory.CreateDirectory(Path.Combine(folder,"breaths"));int j=0;foreach(double d in new[]{.208,.254,.286,.315})Tone(d).Write(Path.Combine(folder,"breaths",(++j)+".wav"));
  foreach(var item in data.cases){string source=Path.Combine(fixtures,item.name+".srt");string hash=StateFiles.Hash(source).ToLowerInvariant();Check(hash==item.sha256,item.name+": genuine original SRT hash equals both attached reports");var cues=Scripts.ParseSrt(File.ReadAllText(source));var plan=AnchoredVoice.Plan(cues);Check(plan.Count==item.stages.Count&&plan.SelectMany(s=>s.Cues.Select(c=>c.Id)).SequenceEqual(cues.Select(c=>c.Id)),item.name+": stage plan and source cue order retained");
   foreach(var stage in item.stages.Where(s=>s.attempts.Count>0))foreach(var attempt in stage.attempts){var original=cues.Where(c=>stage.ids.Contains(c.Id)).ToList();var proposed=VoiceRenderReport.Snapshot(original);foreach(var c in proposed)c.Text=attempt.cues.First(x=>x.id==c.Id).text;Check(RepairPolicy.Check(original,proposed).Rejected,item.name+": reject historical proposal with changed content words at cue "+stage.ids[0]);}
   var durations=new Dictionary<string,double>();foreach(var stage in plan){var units=AnchoredVoice.SpeechUnits(stage.Text);int words=units.Sum(s=>new Cue{Text=s}.Words);foreach(string unit in units)durations[unit]=stage.Budget*.95*new Cue{Text=unit}.Words/words;}
   var options=new RenderOptions{Anchored=true,Locked=false,GentleFit=false,MinSpeed=.9,MaxSpeed=1.25,BaseSpeed=1,Breathing=BreathMode.Auto,NormalizeLoudness=item.name=="van 4",CheckpointRoot=Path.Combine(folder,"stage-cache"),ReportContext=new VoiceReportContext{SourcePath=source,SourceCues=VoiceRenderReport.Snapshot(cues)}};
   var engine=new ReplayEngine{Root=folder,VoiceName="SYNTHETIC FIXTURE (not Steven/Chatterbox)",DeviceMode="cpu",Durations=durations};string wav=Renderer.Render(cues,engine,options,Path.Combine(folder,item.name+".wav"),(p,m)=>{});string stem=Path.ChangeExtension(wav,null);var final=Scripts.ParseSrt(File.ReadAllText(stem+".final.srt"));var originalCues=Scripts.ParseSrt(File.ReadAllText(source));
   Check(final.Select(c=>c.Text).SequenceEqual(originalCues.Select(c=>c.Text))&&final.Select(c=>c.Start+"|"+c.End).SequenceEqual(originalCues.Select(c=>c.Start+"|"+c.End)),item.name+": synthetic full render leaves narration and every source timecode unchanged");
   string vi=File.ReadAllText(stem+".final.vi.txt");Check(final.All(c=>vi.Contains("EN: "+c.Text))&&vi.Split(new[]{"VI: [CHƯA DỊCH]"},StringSplitOptions.None).Length-1==final.Count,item.name+": comparison TXT matches final SRT and declares untranslated Vietnamese");
   Check(FinalAudio.PcmFrames(wav)==(long)Math.Round(cues.Last().End*24000)&&StateFiles.Hash(source).ToLowerInvariant()==hash,item.name+": exact full WAV duration and original source bytes preserved");
   int calls=engine.Calls;string again=Renderer.Render(cues,engine,options,Path.Combine(folder,item.name+".wav"),(p,m)=>{});Check(engine.Calls==calls&&again!=wav,item.name+": repeated export reuses all stage PCM checkpoints and preserves previous output");
   if(item.name=="van 5"){var stage=item.stages.Single(x=>x.ids[0]==9);Check(Math.Abs(stage.final_natural-stage.probe_natural-.476)<.001,"VAN5 9–12: historical probe/final difference is 0.476 seconds, not a successful AI repair");Check(options.RunReport.Stages.Single(s=>s.CueIds.Contains(9)).After.HasValue,"VAN5 9–12: stage completes and is measured in the synthetic integration run");}
   if(item.name=="van 6")Check(item.old_wav_changed_ids.SequenceEqual(new[]{5,6,7,8,30,31}),"VAN6: old WAV changed six source cues; source-only edits cannot silently replace final subtitles");
  }
  Console.WriteLine("TOTAL VAN REGRESSION "+count+" passed. Historical report audit + genuine SRT with SYNTHETIC TTS; not a real Chatterbox/Qwen/GPU rerender.\nOutputs: "+folder);return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
